package com.smarthub.plus;
import android.app.Instrumentation;import android.content.Context;import android.os.*;import java.net.*;import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicBoolean;
/** Test APK only: a real loopback HTTP WAV source, never labelled as a broadcast or user station. */
final class IPAudioAcceptance33 {
 static void run(Instrumentation test,Context c,Bundle out)throws Exception{
  String physical="TEST_IP_AUDIO_33";ServerSocket server=new ServerSocket(0,4,InetAddress.getByName("127.0.0.1"));server.setSoTimeout(12000);AtomicBoolean requested=new AtomicBoolean();ByteBuffer b=ByteBuffer.allocate(44+16000*2*8).order(ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes(StandardCharsets.US_ASCII)).putInt(b.capacity()-8).put("WAVEfmt ".getBytes(StandardCharsets.US_ASCII)).putInt(16).putShort((short)1).putShort((short)1).putInt(16000).putInt(32000).putShort((short)2).putShort((short)16).put("data".getBytes(StandardCharsets.US_ASCII)).putInt(b.capacity()-44);while(b.hasRemaining())b.putShort((short)0);byte[] wav=b.array();Thread http=new Thread(()->{try(Socket client=server.accept()){client.setSoTimeout(3000);BufferedReader input=new BufferedReader(new InputStreamReader(client.getInputStream(),StandardCharsets.US_ASCII));int count=0;String line;while((line=input.readLine())!=null&&!line.isEmpty()&&++count<80){}requested.set(true);OutputStream stream=client.getOutputStream();stream.write(("HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nContent-Length: "+wav.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));stream.write(wav);stream.flush();}catch(Exception ignored){}},"test-http-audio");http.start();
  IPAudioController[] audio={null};AtomicBoolean nativeMuted=new AtomicBoolean(),restored=new AtomicBoolean();String url="http://127.0.0.1:"+server.getLocalPort()+"/test.wav";try{new IPAudioBinding(url,150,0,true).save(c,physical);IPAudioBinding loaded=IPAudioBinding.read(c,physical);out.putBoolean("ip_audio_encrypted_roundtrip",loaded!=null&&loaded.url.equals(url)&&loaded.delay==150&&loaded.enabled);if(!out.getBoolean("ip_audio_encrypted_roundtrip"))throw new AssertionError("IP audio secure roundtrip failed");test.runOnMainSync(()->{audio[0]=new IPAudioController(c,on->{if(on)restored.set(true);else nativeMuted.set(true);});audio[0].apply(physical);});boolean[] playing={false};for(int n=0;n<100;n++){Thread.sleep(100);test.runOnMainSync(()->playing[0]=audio[0].playing());if(playing[0])break;}out.putBoolean("ip_audio_http_playback",requested.get()&&playing[0]&&nativeMuted.get());if(!out.getBoolean("ip_audio_http_playback"))throw new AssertionError("IP audio HTTP decoder did not start");}finally{test.runOnMainSync(()->{if(audio[0]!=null)audio[0].close();});server.close();IPAudioBinding.remove(c,physical);}out.putBoolean("ip_audio_restores_original",restored.get());if(!restored.get())throw new AssertionError("IP audio did not request original audio restore");
 }
}
